import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i + max(range(i, m), key=lambda x: abs(A[x][i]))
            A[i], A[max_row] = A[max_row], A[i]
            if A[i][i] == 0:
                continue
            for j in range(n):
                A[i][j] /= A[i][i]
            for k in range(m):
                if k != i and A[k][i] != 0:
                    factor = A[k][i]
                    for j in range(n):
                        A[k][j] -= factor * A[i][j]
        return A

    def matrix_multiply(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[0] * p for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def determinant(A):
        m, n = len(A), len(A[0])
        if m != n:
            raise ValueError("Matrix must be square")
        if m == 1:
            return A[0][0]
        det = 0
        for i in range(n):
            submatrix = [row[:i] + row[i+1:] for row in A[1:]]
            det += (-1) ** i * A[0][i] * determinant(submatrix)
        return det

    def min_rank(A):
        rank = 0
        A_rref = gaussian_elimination(A)
        for row in A_rref:
            if any(row):
                rank += 1
        return rank

    def communication_complexity(n, kappa):
        return n**2 / kappa**2

    n_values = [5, 10, 15, 20, 30, 40]
    total_metric_value = 0
    instances_tested = 0
    conjecture_holds = True
    counterexample = ""

    for n in n_values:
        kappa = random.randint(1, 10)
        G = [[random.choice([0, 1]) if i != j else 0 for j in range(n)] for i in range(n)]
        connectivity = sum(sum(row) for row in G) / (n * (n - 1))

        if connectivity < kappa:
            continue

        A = [[random.random() for _ in range(n)] for _ in range(n)]
        rank = min_rank(A)

        instances_tested += n
        total_metric_value += communication_complexity(n, kappa)

        expected_bound = communication_complexity(n, kappa)
        empirical_bound = rank ** 2

        if empirical_bound > expected_bound:
            conjecture_holds = False
            counterexample = f"n={n}, kappa={kappa}, rank={rank}, expected_bound={expected_bound}, empirical_bound={empirical_bound}"

    return {
        "metric_name": "communication_complexity",
        "metric_value": total_metric_value / instances_tested,
        "instances_tested": instances_tested,
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    import sys
    seeds = [int(x) for x in sys.argv[1:]] if sys.argv[1:] else [2**i + 3 for i in range(5, 8)]

    results = []
