                if random.random() < 0.5:
                    G[i].add(j)
                    G[j].add(i)
        return G

    def connectivity(G):
        visited = [False] * len(G)

        def dfs(node):
            stack = [node]
            while stack:
                node = stack.pop()
                if not visited[node]:
                    visited[node] = True
                    for neighbor in G[node]:
                        stack.append(neighbor)

        dfs(0)
        return sum(visited) == len(G)

    def simulate_quantum_walk(G, n):
